import subprocess
def run(*a, timeout=5):
    import subprocess as sp
    try:
        p=sp.run(["./executable"]+list(a), capture_output=True, timeout=timeout)
        return p
    except sp.TimeoutExpired as e:
        print("TIMEOUT", e.stdout[:500] if e.stdout else None, e.stderr[:500] if e.stderr else None)
        return None

# interactive mode: no subcommand, with timeout 2s
import subprocess as sp
for args in [["assets/test_model.obj"], ["-b","assets/test_model.obj"], ["assets/test_model.obj","-b"]]:
    print("ARGS",args)
    try:
        p=sp.run(["./executable"]+args, capture_output=True, timeout=3)
        print("exit",p.returncode,"stdout len",len(p.stdout) if p.stdout else 0,"stderr",p.stderr[:1000] if p.stderr else b"")
        if p.stdout:
            print(repr(p.stdout[:1000]))
    except sp.TimeoutExpired as e:
        print("TIMEOUT stdout len", len(e.stdout) if e.stdout else 0, "stderr", e.stderr[:1000] if e.stderr else None)
        if e.stdout:
            print(repr(e.stdout[:2000]))
    print("---")
PY
"}

