import subprocess
def run(*a, timeout=10):
    import subprocess as sp
    return sp.run(["./executable"]+list(a), capture_output=True, timeout=timeout)

def make_obj(path, verts):
    with open(path,"w") as f:
        f.write("mtllib simple.mtl\n")
        f.write("o T\n")
        for v in verts:
            f.write(f"v {v[0]} {v[1]} {v[2]}\n")
        f.write("vn 0 0 1\nusemtl White\ns 1\nf 1//1 2//1 3//1\n")

# tall thin vs short wide
make_obj("/tmp/tall.obj", [(-0.5,-2,0),(0.5,-2,0),(0,2,0)])
make_obj("/tmp/wide.obj", [(-2,-0.5,0),(2,-0.5,0),(0,0.5,0)])
for path in ["//tmp/tall.obj","/tmp/wide.obj","/tmp/tall.obj"]:
    pass
