# Try both: integer coords (x,y) vs centers (x+0.5,y+0.5)

def edge(ax,ay,bx,by,cx,cy):
    return (cx-ax)*(by-ay)-(cy-ay)*(bx-ax)

def inside(px,py, v0,v1,v2):
    # barycentric with >=0 (inclusive)
    e0=edge(v0[0],v0[1],v1[0],v1[1],px,py)
    e1=edge(v1[0],v1[1],v2[0],v2[1],px,py)
