    # need consistent winding: triangle (0,8),(18,8),(9,0) is clockwise? Compute area
    # For inclusive, all >=0 or all <=0
    return (e0>=0 and e1>=0 and e2>=0) or (e0<=0 and e1<=0 and e2<=0)

