def build_lines(gc,gcol,W,H):
    max_h=W//2+2
    eff_h=H if H<=max_h else max_h
    vw=W-1
    vh=eff_h-1
    if vw<1: vw=1
    if vh<1: vh=1
    if H<=max_h:
        first_extra=2
        last_extra=W+H-1
        nlines=vh
    else:
        diff=H-max_h
        first_extra=2+W*((diff+1)//2)
        last_extra=(W+H-1)+W*(diff//2)
        nlines=vh
