        if ka=='-V' or ka=='--version':
            sys.stdout.write("Sloth 0.1\n"); sys.exit(0)
    for a in top_argv:
        ka=a.split('=',1)[0] if '=' in a and a.startswith('-') else a
        if ka=='-h' or ka=='--help':
            sys.stdout.write(TOP_HELP); sys.exit(0)
    # Parse top args
    has_b=False; has_x=False; has_y=False; has_z=False
    x_val=None; y_val=None; z_val=None
